mapper.select:
   select * from (
   	 	select 
	        REPORTUUID reportuuid,
		    TERMID termid,
		    REPORTTYPE reporttype,
            REPROT_NAME reportName,
		    REPORT_DATE reportDate,
		    STARTDATE startdate,
		    ENDDATE enddate,
		    ISSUE_PARTY_ID issuePartyId,
		    ISSUE_PARTY_NAME issuePartyName,
		    REPORTFREQU reportfrequ,
		    SUBMIT_TIME submitTime,
		    CHB_SUBMIT_DEADLINE chbSubmitDeadline,
		    SUBMIT_DEADLINE submitDeadline,
		    SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
		    DATA_STATUS dataStatus,
		    SEND_STATUS sendStatus,
		    STATUS_DATE statusDate,
		    CREATE_USER createUser,
		    CREATE_TIME createTime,
		    UPDATE_USER updateUser,
		    UPDATE_TIME updateTime,
		    ORG_CODE orgCode,
		    DEPT_CODE deptCode,
		    CREATE_DEPT createDept
	    from CHB_SALE_MONTH_REPORT


				CHB_SUBMIT_DEADLINE >= #{submitDeadLineStart}


				and CHB_SUBMIT_DEADLINE <= #{submitDeadLineEnd}



				#{item,jdbcType=VARCHAR}




                #{item,jdbcType=VARCHAR}




				#{item,jdbcType=VARCHAR}



				and STATUS_DATE >= #{statusDateStart}


				and STATUS_DATE <= #{statusDateEnd}


				and SUBMIT_TIME >= #{submitTimeStart}


				and SUBMIT_TIME <= #{submitTimeEnd}


				and termid >= #{termidDateStart}


				and termid <= #{termidDateEnd}



             		#{submitFeedbackStatus,jdbcType=VARCHAR}



				and SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}


				and termid =  #{termid,jdbcType=VARCHAR}


				and date_format(ENDDATE,'%Y-%m')  =  #{enddate,jdbcType=VARCHAR}


   	) t ORDER BY STATUSDATE

select a.REGIST_SEQNO registSeqno, a.SEND_STATUS sendStatus, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUBMIT_TIME submitTime, a.SUBMIT_DEADLINE submitDeadline, a.DATA_STATUS dataStatus, a.INSTITUTION_CODE institutionCode, a.PRD_REGIST_CODE prdRegistCode, a.ACCOUNT_NO accountNo, a.ACCOUNT_NAME accountName, a.TRADE_NO tradeNo, a.TRADE_PS tradePs, a.TRADE_COUNTER_ACC_NO tradeCounterAccNo, a.TRADE_COUNTER_ACC_NAME tradeCounterAccName, a.TRADE_COUNTER_ACC_BANK_NAME tradeCounterAccBankName, a.TRADE_COUNTER_ACC_BANK_NO tradeCounterAccBankNo, a.TRADE_CCY tradeCcy, a.TRADE_AMT tradeAmt, a.TRADE_VDATE tradeVdate, a.TRADE_TIME tradeTime, a.POSTSCRIPT postscript, a.REMARK remark, a.UPDATE_TIME FROM CHB_SALER_STL_DEAL_SUB a /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
/*LEFT JOIN CHB_SUBMIT_STATUS status ON a.SUMIT_SEQ = status.seqno*/ /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ where 1=1
and a.SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}
and a.SEND_STATUS = #{sendStatus}
and a.DATA_STATUS = #{dataStatus}
and a.SUBMIT_DEADLINE between #{searchSubmitDeadlineStart} and #{searchSubmitDeadlineEnd}
and a.STATUS_DATE between #{searchStatusDateStart} and #{searchStatusDateEnd}
and a.SUBMIT_TIME between #{searchSubmitTimeStart} and #{searchSubmitTimeEnd}

select INSTITUTION_NAME from SYS_INSTITUTION
where
INSTITUTION_CODE = #{orgCode,jdbcType=VARCHAR}

select REGIST_BANK_CODE from CHB_ORG_REGIST_BANK_CODE
where
ORG_CODE = #{orgCode,jdbcType=VARCHAR}
